<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRoute} from 'vue-router'
import MarkdownIt from 'markdown-it'
import {loadCatalog,type ArticleContent} from '@/api/content'
import {api} from '@/api/client'
const route=useRoute(),kind=route.path.startsWith('/projects/')?'project':'post'
const entry=ref<ArticleContent|null>(null),liked=ref(false),saved=ref(false),comment=ref(''),notice=ref('')
const comments=ref<Array<{id:number;content:string;nickname:string;created_at:string}>>([])
const markdown=new MarkdownIt({html:false,linkify:true,typographer:true})
const rendered=computed(()=>entry.value?markdown.render(entry.value.content||''): '')
onMounted(async()=>{const data=await loadCatalog();const list=kind==='project'?data.projects:data.posts;entry.value=list.find(e=>e.slug===String(route.params.slug))||null;try{const r=await api.get('/api/articles/'+String(route.params.slug)+'/comments');comments.value=r.data}catch{/* comments endpoint may not be deployed yet */}})
async function action(type:'likes'|'bookmarks'){try{const r=await api.post('/api/articles/'+String(route.params.slug)+'/'+type);if(type==='likes')liked.value=r.data.active;else saved.value=r.data.active}catch{notice.value='请先登录，或稍后重试。'}}
async function submit(){if(!comment.value.trim())return;try{await api.post('/api/comments',{article_slug:route.params.slug,content:comment.value});comment.value='';notice.value='评论已提交';const r=await api.get('/api/articles/'+String(route.params.slug)+'/comments');comments.value=r.data}catch(e){notice.value=e instanceof Error?e.message:'请先登录后发表评论。'}}
</script>
<template><article v-if="entry" class="page-wrap article"><RouterLink :to="kind==='project'?'/projects/':'/posts/'" class="back">← 返回{{kind==='project'?'项目':'随笔'}}</RouterLink><header><span class="eyebrow">{{kind==='project'?'PROJECT NOTES':'JOURNAL ENTRY'}} / {{String(entry.date||'')}}</span><h1>{{entry.title}}</h1><p>{{entry.summary}}</p><div class="tags"><span v-for="t in entry.tags||[]" :key="t">{{t}}</span></div></header><div v-if="entry.cover" class="cover"><img :src="entry.cover" :alt="entry.title"></div><div class="markdown-body" v-html="rendered"></div><section class="interaction"><div class="buttons"><button :class="{on:liked}" @click="action('likes')">♡ 点赞</button><button :class="{on:saved}" @click="action('bookmarks')">☆ 收藏</button></div><h2>评论 {{comments.length}}</h2><div v-for="item in comments" :key="item.id" class="comment"><b>{{item.nickname}}</b><time>{{new Date(item.created_at).toLocaleString('zh-CN')}}</time><p>{{item.content}}</p></div><textarea v-model="comment" rows="4" placeholder="写下友善、具体的评论..."></textarea><div class="submit"><span>{{notice}}</span><button @click="submit">发布评论</button></div></section></article><div v-else class="page-wrap missing"><h1>正在加载内容，或暂未找到这篇文章</h1><RouterLink to="/posts/">返回随笔</RouterLink></div></template>
<style scoped>
.article{max-width:850px;padding-top:65px}.back{color:#817d91;font-size:12px}header{padding:42px 0 30px;border-bottom:1px solid #eae7f2}.article h1{margin:16px 0;font-size:clamp(34px,5vw,52px);letter-spacing:-.06em}.article header p{color:#817d91;line-height:1.9}.tags{display:flex;gap:7px;margin-top:20px}.tags span{padding:5px 10px;background:#f0edff;border-radius:99px;color:#6e5cbd;font-size:10px}.cover{margin:30px 0;border-radius:18px;overflow:hidden}.cover img{width:100%;max-height:460px;object-fit:cover}.markdown-body{padding:25px 0 45px;color:#464255;font-size:15px;line-height:2}.markdown-body :deep(h2){margin-top:2em;font-size:26px}.markdown-body :deep(h3){margin-top:1.7em;font-size:20px}.markdown-body :deep(img){max-width:100%;height:auto;border-radius:12px}.markdown-body :deep(pre){overflow:auto;padding:18px;border-radius:12px;background:#242235;color:#eee}.markdown-body :deep(code){font-family:'DM Mono',monospace;font-size:.9em}.markdown-body :deep(blockquote){margin:1.5em 0;padding:5px 18px;border-left:3px solid #a99cdd;color:#817d91;background:#f6f4fc}.markdown-body :deep(a){color:#7665bd;text-decoration:underline}.interaction{padding:28px 0;border-top:1px solid #eae7f2}.buttons{display:flex;gap:10px}.buttons button{padding:10px 15px;border:1px solid #e7e3f0;border-radius:99px;background:white;color:#716b82}.buttons button.on{color:#7d6bc7;background:#f0edff}.interaction h2{font-size:19px;margin-top:30px}.comment{padding:14px 0;border-bottom:1px solid #eeeaf4}.comment b{font-size:12px}.comment time{margin-left:12px;color:#aaa;font-size:10px}.comment p{color:#686477;font-size:13px}.interaction textarea{width:100%;padding:14px;border:1px solid #e7e3f0;border-radius:13px;resize:vertical}.submit{display:flex;justify-content:space-between;align-items:center;margin-top:12px;color:#918ba2;font-size:11px}.submit button{padding:10px 18px;border:0;border-radius:99px;background:#8170cc;color:white}.missing{text-align:center;padding:100px}
</style>
